import{_ as i,C as n,o as d,c as l,a2 as a,j as t,a as o,E as s}from"./chunks/framework.D0xy3_1I.js";const _=JSON.parse('{"title":"1. Overview","description":"","frontmatter":{},"headers":[],"relativePath":"gdd/overview.md","filePath":"gdd/overview.md"}'),h={name:"gdd/overview.md"},c={id:"_1-3-what-the-prototype-is-built-from",tabindex:"-1"},p={id:"_1-4-controls",tabindex:"-1"};function u(g,e,f,m,b,w){const r=n("Badge");return d(),l("div",null,[e[6]||(e[6]=a('<h1 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Title</strong></td><td>Fishy Find (earlier name: Spot A Fish; working name in the source: Find Fish)</td></tr><tr><td><strong>Genre</strong></td><td>Casual puzzle: find and tap the right object in a crowded 3D aquarium</td></tr><tr><td><strong>Platform</strong></td><td>Web, mobile portrait first (touch and mouse)</td></tr><tr><td><strong>Engine</strong></td><td>Three.js 0.186 for the 3D tank, Phaser 4 for all UI (HUD, target tanks, popups), bundled by Vite</td></tr><tr><td><strong>Status</strong></td><td>Prototype. 60 levels, not yet playtested on a real phone</td></tr></tbody></table><h2 id="_1-1-pitch" tabindex="-1">1.1 Pitch <a class="header-anchor" href="#_1-1-pitch" aria-label="Permalink to &quot;1.1 Pitch&quot;">​</a></h2><p>A round 3D fish tank is full of fish. Two target tanks above it ask for specific species. Tap the right fish before your Backup tray fills up. Wrong taps go into a 7-slot Backup; when it is full you lose.</p><h2 id="_1-2-target-player" tabindex="-1">1.2 Target player <a class="header-anchor" href="#_1-2-target-player" aria-label="Permalink to &quot;1.2 Target player&quot;">​</a></h2><p><em>TBD</em></p>',6)),t("h2",c,[e[0]||(e[0]=o("1.3 What the prototype is built from ",-1)),s(r,{type:"tip",text:"Live"}),e[1]||(e[1]=o()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#_1-3-what-the-prototype-is-built-from","aria-label":'Permalink to "1.3 What the prototype is built from <Badge type="tip" text="Live" />"'},"​",-1))]),e[7]||(e[7]=a("<ul><li>Fish are <strong>49 static 3D models</strong> (single mesh and one texture each, <code>public/models/fish/&lt;name&gt;/</code>, prepared by <code>scripts/prep-fish.py</code>): 12 from ChatGPT, 6 from Codex and 31 from Tripo, including a whale, a shark and a sea horse that never are targets. Each species is one model; look-alike decoys of the same colour family appear more often in harder levels. There is no skeleton: the body wave is done in the vertex shader.</li><li><strong>Artist models</strong> are used for the octopus, the jellyfish, the clam and the decoration: the clay pot, the stone pillars and statue, the anchor, three corals and the glass bottle (<code>public/models/&lt;name&gt;/</code>, one <code>model.fbx</code> and one <code>tex.png</code> each; the corals sway in the current, the anchor rocks, the Atlantis crystals glimmer). The rest is a <strong>mesh built in code</strong>, used as a placeholder: rocks, houses, arches, seaweed, anemones, the treasure chest, the wreck, barrels, crystals, the pump tube, the food bucket and the pearl.</li><li><strong>The UI is art too:</strong> the pop-ups (Pause, Out of space, Purchase, Well Done, Level failed), the buttons and icons are pictures in <code>public/ui/bf/</code> and <code>public/ui/new/</code>, drawn by Phaser; the target tanks, the Backup and the loading screen use pictures in <code>public/ui/tanks/</code> and <code>public/ui/load/</code>; the logo is <code>public/ui/load/logo.png</code>.</li><li><strong>6 tank shapes</strong> (cylinder, bowl, rounded box, hexagon, flower, heart) and <strong>6 hall looks</strong>, one for every 10 levels.</li><li>Fish swim with a body wave, turn, and react when scared. They bite the food when it is fed. All 49 blink: 32 by turning the eye on their texture into the colour of the skin next to it (the colour is read from the rendered fish), 17 by a lid made of the body&#39;s own triangles round the eye that fades in over it (<code>refineLid</code> / <code>geoLid</code> in <code>game/src/main.js</code>; for 8 of them the eye position is given by hand in <code>EYE_AT</code>).</li><li>Fish get a soft dark outline taken from their own colour.</li><li>The tank sits in an &quot;aquarium hall&quot; 3D scene. Glass and water bend the view through a post-process lens; the water surface reflects the sky and ripples on impact.</li><li>Sounds and music are recorded files in <code>public/sfx</code> (see <code>sounds.md</code> for which one plays when); a sound without a file does not play.</li></ul>",1)),t("h2",p,[e[3]||(e[3]=o("1.4 Controls ",-1)),s(r,{type:"tip",text:"Live"}),e[4]||(e[4]=o()),e[5]||(e[5]=t("a",{class:"header-anchor",href:"#_1-4-controls","aria-label":'Permalink to "1.4 Controls <Badge type="tip" text="Live" />"'},"​",-1))]),e[8]||(e[8]=a('<ul><li>Drag to rotate the tank (after a 18 px move, so a light tap does not nudge it). Pinch or mouse wheel to zoom. <strong>Two fingers dragging up or down move the view</strong> up and down (a long way when zoomed in; when the whole tank is in view it gives a little and springs back, so the player feels it work); two fingers pinching only zoom. A button resets the camera.</li><li>On desktop, hovering a fish enlarges it and shows a <strong>gold outline</strong> so the player knows which fish a click will hit. On touch the outline shows only while the finger is down. A tap on the water makes the nearby fish dart away; the surface only ripples when the tap is at or near the surface.</li></ul><h2 id="_1-5-look-and-sound" tabindex="-1">1.5 Look and sound <a class="header-anchor" href="#_1-5-look-and-sound" aria-label="Permalink to &quot;1.5 Look and sound&quot;">​</a></h2><p>See <a href="./art-audio">Art and audio</a>.</p>',3))])}const k=i(h,[["render",u]]);export{_ as __pageData,k as default};
